// SPDX-License-Identifier: AGPL-3.0-or-later
// Starboard Protocol — reference implementation (C99 port)
// Copyright (C) 2026 James H. All rights reserved.
// Dual licensing: see COMMERCIAL-LICENSE.md.
//
// geometry.c — Vec3 arithmetic (pinned expansion order) and the linear
// encounter kernel screen(). Only +,-,*,/,sqrt on this path.

/* #include "starboard.h" (amalgamated) */
#include <math.h>

Vec3 sb_vadd(Vec3 a, Vec3 b)
{
    Vec3 r;
    r.x = a.x + b.x;
    r.y = a.y + b.y;
    r.z = a.z + b.z;
    return r;
}

Vec3 sb_vsub(Vec3 a, Vec3 b)
{
    Vec3 r;
    r.x = a.x - b.x;
    r.y = a.y - b.y;
    r.z = a.z - b.z;
    return r;
}

Vec3 sb_vscale(Vec3 a, double s)
{
    Vec3 r;
    r.x = a.x * s;
    r.y = a.y * s;
    r.z = a.z * s;
    return r;
}

Vec3 sb_vdiv(Vec3 a, double s)
{
    Vec3 r;
    r.x = a.x / s;
    r.y = a.y / s;
    r.z = a.z / s;
    return r;
}

/* Pinned expansion order (SPEC §3.5): (x*ox + y*oy) + z*oz. */
double sb_vdot(Vec3 a, Vec3 b)
{
    return ((a.x * b.x) + (a.y * b.y)) + (a.z * b.z);
}

Vec3 sb_vcross(Vec3 a, Vec3 b)
{
    Vec3 r;
    r.x = (a.y * b.z) - (a.z * b.y);
    r.y = (a.z * b.x) - (a.x * b.z);
    r.z = (a.x * b.y) - (a.y * b.x);
    return r;
}

double sb_vnorm2(Vec3 a)
{
    return sb_vdot(a, a);
}

double sb_vnorm(Vec3 a)
{
    return sqrt(sb_vnorm2(a));
}

Vec3 sb_vnormalized(Vec3 a)
{
    const double n = sb_vnorm(a);
    Vec3 z;
    if (n > 0.0)
    {
        return sb_vdiv(a, n);
    }
    z.x = 0.0;
    z.y = 0.0;
    z.z = 0.0;
    return z;
}

Vec3 sb_vquantize(Vec3 v, double q)
{
    Vec3 r;
    r.x = sb_quantize(v.x, q);
    r.y = sb_quantize(v.y, q);
    r.z = sb_quantize(v.z, q);
    return r;
}

CraftState sb_canonicalize(CraftState s)
{
    CraftState c;
    c.position = sb_vquantize(s.position, SB_Q_POS_M);
    c.velocity = sb_vquantize(s.velocity, SB_Q_VEL_MPS);
    return c;
}

Conjunction sb_screen(CraftState a, CraftState b, double horizon_s,
                      double r_screen)
{
    const Vec3 dr = sb_vsub(b.position, a.position);
    const Vec3 dv = sb_vsub(b.velocity, a.velocity);
    const double dv2 = sb_vdot(dv, dv);
    Conjunction c;
    double t_raw;

    c.rel_velocity = dv;
    c.pc = 0.0;

    if (dv2 < 1.0e-12)
    {
        t_raw = 0.0;
    }
    else
    {
        t_raw = -(sb_vdot(dr, dv)) / dv2;
    }

    /* An out-of-window TCA (past, or beyond the horizon) means the pair is
     * assessed AT ITS CURRENT SEPARATION: a pair already inside the bubble
     * is detected regardless of where its linear TCA falls. */
    if ((t_raw <= 0.0) || (t_raw > horizon_s))
    {
        c.t_ca = 0.0;
        c.miss_vector = dr;
    }
    else
    {
        c.t_ca = t_raw;
        c.miss_vector = sb_vadd(dr, sb_vscale(dv, t_raw));
    }
    c.miss_distance = sb_vnorm(c.miss_vector);
    c.detected = (c.miss_distance < r_screen);
    return c;
}

/* ==== propagator.c ==== */
// SPDX-License-Identifier: AGPL-3.0-or-later
// Starboard Protocol — reference implementation (C99 port)
// Copyright (C) 2026 James H. All rights reserved.
// Dual licensing: see COMMERCIAL-LICENSE.md.
//
// propagator.c — fixed-step RK4 over two-body + J2 zonal dynamics. Pinned
// stage order, pinned intra-vector expansion order, floor-via-(long)-cast step
// decomposition. Algebraic ops + sqrt only; no transcendental on this path.

/* #include "starboard.h" (amalgamated) */
#include <math.h>

Vec3 sb_accel_j2(Vec3 r)
{
    const double r2 = sb_vnorm2(r);
    const double rn = sqrt(r2);
    const double inv_r3 = 1.0 / (r2 * rn);
    Vec3 a = sb_vscale(r, (-SB_MU_EARTH_M3S2 * inv_r3));
    const double zr2 = (r.z * r.z) / r2;
    const double re2 = SB_R_EARTH_M * SB_R_EARTH_M;
    const double f = (-1.5 * SB_J2_EARTH * SB_MU_EARTH_M3S2 * re2) *
                     (inv_r3 / r2);
    const double c_xy = 1.0 - (5.0 * zr2);
    const double c_z = 3.0 - (5.0 * zr2);
    a.x += (f * r.x) * c_xy;
    a.y += (f * r.y) * c_xy;
    a.z += (f * r.z) * c_z;
    return a;
}

void sb_rk4_step(CraftState *s, double h)
{
    const Vec3 k1v = s->velocity;
    const Vec3 k1a = sb_accel_j2(s->position);
    const Vec3 k2v = sb_vadd(s->velocity, sb_vscale(k1a, 0.5 * h));
    const Vec3 k2a = sb_accel_j2(sb_vadd(s->position, sb_vscale(k1v, 0.5 * h)));
    const Vec3 k3v = sb_vadd(s->velocity, sb_vscale(k2a, 0.5 * h));
    const Vec3 k3a = sb_accel_j2(sb_vadd(s->position, sb_vscale(k2v, 0.5 * h)));
    const Vec3 k4v = sb_vadd(s->velocity, sb_vscale(k3a, h));
    const Vec3 k4a = sb_accel_j2(sb_vadd(s->position, sb_vscale(k3v, h)));
    const double h6 = h / 6.0;
    /* pos += ((k1v+k4v) + (k2v+k3v)*2) * h6 */
    s->position = sb_vadd(s->position,
        sb_vscale(sb_vadd(sb_vadd(k1v, k4v),
                          sb_vscale(sb_vadd(k2v, k3v), 2.0)), h6));
    s->velocity = sb_vadd(s->velocity,
        sb_vscale(sb_vadd(sb_vadd(k1a, k4a),
                          sb_vscale(sb_vadd(k2a, k3a), 2.0)), h6));
}

CraftState sb_propagate(CraftState s0, double dt)
{
    CraftState s = s0;
    double sign;
    double adt;
    double h;
    long n_full;
    long i;
    double rem;

    if (dt == 0.0)
    {
        return s;
    }
    sign = (dt < 0.0) ? -1.0 : 1.0;
    adt = sign * dt;
    /* Domain guard (SPEC §3.7): NaN/Inf/absurd |dt| would be UB in the
     * (long) cast or an hours-long loop. Bit-neutral inside the domain. */
    if (!(adt <= SB_PROP_DT_MAX_S))
    {
        return s;
    }
    h = sign * SB_PROP_STEP_S;
    n_full = (long)(adt / SB_PROP_STEP_S);
    for (i = 0; i < n_full; ++i)
    {
        sb_rk4_step(&s, h);
    }
    rem = adt - ((double)n_full * SB_PROP_STEP_S);
    if (rem > 0.0)
    {
        sb_rk4_step(&s, sign * rem);
    }
    return s;
}

