//
// screening.c — canonical conjunction search over a bounded J2 arc.
// Grid walk on the 32 s range-rate sign grid + fixed 48-step bisection.

/* #include "starboard.h" (amalgamated) */
#include <math.h>

void sb_radial_bounds(CraftState s, double *r_lo, double *r_hi)
{
    const double rn = sb_vnorm(s.position);
    const double v2 = sb_vdot(s.velocity, s.velocity);
    const double energy = (0.5 * v2) - (SB_MU_EARTH_M3S2 / rn);
    double a;
    double h;
    double e2;
    double e;

    if (energy >= 0.0)
    {
        *r_lo = 0.0;
        *r_hi = 1.0e18;
        return;
    }
    a = -SB_MU_EARTH_M3S2 / (2.0 * energy);
    h = sb_vnorm(sb_vcross(s.position, s.velocity));
    e2 = 1.0 + (((2.0 * energy) * h * h) /
                (SB_MU_EARTH_M3S2 * SB_MU_EARTH_M3S2));
    if (e2 < 0.0)
    {
        e2 = 0.0;
    }
    e = sqrt(e2);
    *r_lo = a * (1.0 - e);
    *r_hi = a * (1.0 + e);
}

/* g(t) = dr.dv at time t; optionally returns dr. */
static double sb_g_at(CraftState a0, CraftState b0, double t, Vec3 *dr_out)
{
    const CraftState sa = sb_propagate(a0, t);
    const CraftState sb = sb_propagate(b0, t);
    const Vec3 dr = sb_vsub(sb.position, sa.position);
    const Vec3 dv = sb_vsub(sb.velocity, sa.velocity);
    if (dr_out != NULL)
    {
        *dr_out = dr;
    }
    return sb_vdot(dr, dv);
}

static bool sb_finalize(CraftState a0, CraftState b0, Sym33 cov_a, Sym33 cov_b,
                        double r_hb, double t_star, OrbitConjunction *oc)
{
    const double t_q = sb_quantize(t_star, SB_Q_TIME_S);
    Conjunction c;
    oc->a_tca = sb_canonicalize(sb_propagate(a0, t_q));
    oc->b_tca = sb_canonicalize(sb_propagate(b0, t_q));
    c.t_ca = t_q;
    c.miss_vector = sb_vsub(oc->b_tca.position, oc->a_tca.position);
    c.rel_velocity = sb_vsub(oc->b_tca.velocity, oc->a_tca.velocity);
    c.miss_distance = sb_vnorm(c.miss_vector);
    c.detected = (c.miss_distance < SB_R_SCREEN_M);
    c.pc = 0.0;
    if (c.detected)
    {
        c.pc = sb_starboard_pc(&c, sb_combined_covariance(cov_a, cov_b), r_hb);
    }
    oc->conj = c;
    return c.detected;
}

bool sb_screen_orbits(CraftState a0_in, CraftState b0_in,
                      Sym33 cov_a, Sym33 cov_b, double r_hb, double arc_s,
                      OrbitConjunction *out)
{
    const CraftState a0 = sb_canonicalize(a0_in);
    const CraftState b0 = sb_canonicalize(b0_in);
    double arc = arc_s;
    double alo;
    double ahi;
    double blo;
    double bhi;
    double gap;
    Vec3 dr0;
    double g0;
    bool inside_now;
    CraftState ma;
    CraftState mb;
    long whole;
    double g_prev;
    double t_prev;
    double step;
    double t;

    if (arc > SB_SCREEN_ARC_MAX_S)
    {
        arc = SB_SCREEN_ARC_MAX_S;
    }
    /* !(arc > 0) also rejects a NaN arc, which `arc <= 0` let through into
     * a grid loop that never terminated (SPEC §3.7). */
    if (!(arc > 0.0))
    {
        return false;
    }

    sb_radial_bounds(a0, &alo, &ahi);
    sb_radial_bounds(b0, &blo, &bhi);
    gap = (alo > bhi) ? (alo - bhi) : (blo - ahi);
    if (gap > SB_R_SCREEN_M)
    {
        return false;
    }

    /* t = 0: inside-bubble, receding (at/past closest approach but still
     * inside the screening radius). */
    g0 = sb_g_at(a0, b0, 0.0, &dr0);
    inside_now = (sb_vnorm(dr0) < SB_R_SCREEN_M);
    if ((g0 >= 0.0) && inside_now)
    {
        if (sb_finalize(a0, b0, cov_a, cov_b, r_hb, 0.0, out))
        {
            return true;
        }
    }

    /* Grid samples at exact multiples of SCREEN_STEP_S are MARCHED
     * incrementally: each 32 s sample is exactly 8 whole PROP_STEP_S steps
     * with no partial step, so advancing the cached states is the identical
     * whole-step sequence as propagate-from-epoch — bit-equal by the pinned
     * step decomposition (propagator.c), ~16x cheaper. The final clamped
     * sample (t = arc when arc is not a grid multiple) and all bisection
     * mids use from-epoch sb_propagate(), whose bits are the definition. */
    ma = a0;
    mb = b0;
    step = SB_SCREEN_STEP_S;
    whole = (long)(step / SB_PROP_STEP_S);
    g_prev = g0;
    t_prev = 0.0;
    for (t = ((step < arc) ? step : arc); ;
         t = ((t + step) < arc) ? (t + step) : arc)
    {
        double g_now;
        if (t == (t_prev + step))
        {
            long k;
            Vec3 dr;
            Vec3 dv;
            for (k = 0; k < whole; ++k)
            {
                sb_rk4_step(&ma, SB_PROP_STEP_S);
                sb_rk4_step(&mb, SB_PROP_STEP_S);
            }
            dr = sb_vsub(mb.position, ma.position);
            dv = sb_vsub(mb.velocity, ma.velocity);
            g_now = sb_vdot(dr, dv);
        }
        else
        {
            g_now = sb_g_at(a0, b0, t, NULL);
        }
        if ((g_prev < 0.0) && (g_now >= 0.0))
        {
            double lo = t_prev;
            double hi = t;
            int i;
            for (i = 0; i < SB_TCA_BISECT_ITERS; ++i)
            {
                const double mid = 0.5 * (lo + hi);
                if (sb_g_at(a0, b0, mid, NULL) < 0.0)
                {
                    lo = mid;
                }
                else
                {
                    hi = mid;
                }
            }
            if (sb_finalize(a0, b0, cov_a, cov_b, r_hb,
                            0.5 * (lo + hi), out))
            {
                return true;
            }
        }
        g_prev = g_now;
        t_prev = t;
        if (t >= arc)
        {
            break;
        }
    }

    /* Fallback: an APPROACHING pair already inside the screening radius whose
     * TCA lies beyond the bounded arc produces no sign change above — but it
     * is inside the bubble NOW and MUST be reported (SPEC §4.2a). */
    if (inside_now)
    {
        if (sb_finalize(a0, b0, cov_a, cov_b, r_hb, 0.0, out))
        {
            return true;
        }
    }
    return false;
}

