// rules.c — canonical identity, trust projection, conjunction id (FNV-1a) and
// the Canonical Pair Transform verdict.

/* #include "starboard.h" (amalgamated) */

/* --- id.hpp --- */
ObjectId sb_make_object_id(const char *s)
{
    ObjectId id;
    int i = 0;
    while ((i < 12) && (s[i] != '\0'))
    {
        char ch = s[i];
        if ((ch >= 'a') && (ch <= 'z'))
        {
            ch = (char)(ch - ('a' - 'A'));
        }
        id.c[i] = ch;
        ++i;
    }
    while (i < 12)
    {
        id.c[i] = '\0';
        ++i;
    }
    return id;
}

int sb_id_compare(const ObjectId *a, const ObjectId *b)
{
    int i;
    for (i = 0; i < 12; ++i)
    {
        const unsigned char x = (unsigned char)a->c[i];
        const unsigned char y = (unsigned char)b->c[i];
        if (x != y)
        {
            return (x < y) ? -1 : 1;
        }
    }
    return 0;
}

bool sb_id_equal(const ObjectId *a, const ObjectId *b)
{
    return sb_id_compare(a, b) == 0;
}

/* --- trust.hpp --- */
bool sb_effective_can_maneuver(TrustLevel trust, bool asserted)
{
    return (trust == TRUST_VERIFIED) ? asserted : false;
}

Tier sb_effective_tier(TrustLevel trust, Tier asserted)
{
    return (trust == TRUST_VERIFIED) ? asserted : TIER_OPERATIONAL;
}

/* --- conjunction id (FNV-1a-64) --- */
/* The 36-byte message the conjunction id hashes (SPEC §9.3):
 * lo_id(12) || hi_id(12) || LE64(tca_epoch_ms / TCA_BUCKET_MS) ||
 * LE32(RULESET_ID). Split out so the CBMC proof of Theorem 1 can show the
 * MESSAGE is identical from both perspectives (verification/cbmc); the id
 * then agrees because FNV-1a is a pure function of it. */
void sb_conjunction_id_message(const ObjectId *a, const ObjectId *b,
                               uint64_t tca_epoch_ms,
                               uint8_t msg[SB_CONJ_ID_MSG_BYTES])
{
    const bool a_lo = (sb_id_compare(a, b) <= 0);
    const ObjectId *lo = a_lo ? a : b;
    const ObjectId *hi = a_lo ? b : a;
    const uint64_t bucket = tca_epoch_ms / SB_TCA_BUCKET_MS;
    uint32_t i;
    for (i = 0U; i < 12U; ++i)
    {
        msg[i] = (uint8_t)lo->c[i];
        msg[12U + i] = (uint8_t)hi->c[i];
    }
    for (i = 0U; i < 8U; ++i)
    {
        msg[24U + i] = (uint8_t)(bucket >> (8U * i));
    }
    for (i = 0U; i < 4U; ++i)
    {
        msg[32U + i] = (uint8_t)((uint32_t)SB_RULESET_ID >> (8U * i));
    }
}

uint64_t sb_fnv1a64(const uint8_t *msg, uint32_t n)
{
    const uint64_t prime = 1099511628211ULL;
    uint64_t h = 14695981039346656037ULL;
    uint32_t i;
    for (i = 0U; i < n; ++i)
    {
        h ^= (uint64_t)msg[i];
        h *= prime;
    }
    return h;
}

uint64_t sb_conjunction_id(const ObjectId *a, const ObjectId *b,
                           uint64_t tca_epoch_ms)
{
    uint8_t msg[SB_CONJ_ID_MSG_BYTES];
    sb_conjunction_id_message(a, b, tca_epoch_ms, msg);
    return sb_fnv1a64(msg, SB_CONJ_ID_MSG_BYTES);
}

/* --- rule predicates ---
 * SB_PROOF_ABSTRACT_PREDICATES is defined ONLY by the CBMC proof of Theorem 1
 * (verification/cbmc): it removes these two bodies so the proof can quantify
 * over EVERY possible predicate function. Never defined in a flight build. */
#ifdef SB_PROOF_ABSTRACT_PREDICATES
bool sb_overtakes(const CraftDescriptor *x, const CraftDescriptor *y);
bool sb_sees_on_starboard(const CraftDescriptor *x, const CraftDescriptor *y);
#else
static bool sb_overtakes(const CraftDescriptor *x, const CraftDescriptor *y)
{
    const double sx = sb_vnorm(x->state.velocity);
    const double sy = sb_vnorm(y->state.velocity);
    Vec3 dv;
    double dvn;
    if ((sx - sy) <= SB_EPS_SPEED_MPS)
    {
        return false;
    }
    if (sy <= SB_EPS_SPEED_MPS)
    {
        return false;
    }
    dv = sb_vsub(x->state.velocity, y->state.velocity);
    dvn = sb_vnorm(dv);
    if (dvn <= SB_EPS_SPEED_MPS)
    {
        return false;
    }
    return sb_vdot(dv, y->state.velocity) > ((SB_OVERTAKE_COS * dvn) * sy);
}

static bool sb_sees_on_starboard(const CraftDescriptor *x,
                                 const CraftDescriptor *y)
{
    const Vec3 starboard =
        sb_vcross(sb_vnormalized(x->state.velocity),
                  sb_vnormalized(x->state.position));
    const Vec3 dv = sb_vsub(y->state.velocity, x->state.velocity);
    const double dvn = sb_vnorm(dv);
    if (dvn <= SB_EPS_SPEED_MPS)
    {
        const Vec3 to_y = sb_vsub(y->state.position, x->state.position);
        return sb_vdot(to_y, starboard) > SB_EPS_LATERAL_M;
    }
    return -(sb_vdot(dv, starboard)) > (SB_EPS_BEARING * dvn);
}
#endif

/* --- evaluate ---
 * The verdict consumes ONLY the descriptors (states at TCA + registry facts)
 * and the epoch. The Conjunction gates WHETHER evaluate runs (sb_actionable,
 * SPEC §4.7) — it is deliberately not a parameter. */
GiveWayVerdict sb_evaluate(const CraftDescriptor *self,
                           const CraftDescriptor *other,
                           uint64_t tca_epoch_ms)
{
    const bool self_is_lo =
        (sb_id_compare(&self->object_id, &other->object_id) <= 0);
    const CraftDescriptor *lo = self_is_lo ? self : other;
    const CraftDescriptor *hi = self_is_lo ? other : self;
    const uint64_t cid =
        sb_conjunction_id(&lo->object_id, &hi->object_id, tca_epoch_ms);
    bool lo_gives_way;
    DecidingRule rule;
    const bool cm_lo = sb_effective_can_maneuver(lo->trust, lo->can_maneuver);
    const bool cm_hi = sb_effective_can_maneuver(hi->trust, hi->can_maneuver);
    const Tier tier_lo = sb_effective_tier(lo->trust, lo->tier);
    const Tier tier_hi = sb_effective_tier(hi->trust, hi->tier);
    GiveWayVerdict v;

    if (cm_lo != cm_hi)
    {
        lo_gives_way = cm_lo;
        rule = RULE_CAPABILITY;
    }
    else if (tier_lo != tier_hi)
    {
        lo_gives_way = ((uint8_t)tier_lo < (uint8_t)tier_hi);
        rule = RULE_TIER;
    }
    else
    {
        const bool lo_overtakes = sb_overtakes(lo, hi);
        const bool hi_overtakes = sb_overtakes(hi, lo);
        if (lo_overtakes != hi_overtakes)
        {
            lo_gives_way = lo_overtakes;
            rule = RULE_OVERTAKING;
        }
        else
        {
            const bool lo_sees = sb_sees_on_starboard(lo, hi);
            const bool hi_sees = sb_sees_on_starboard(hi, lo);
            if (lo_sees != hi_sees)
            {
                lo_gives_way = lo_sees;
                rule = RULE_STARBOARD;
            }
            else
            {
                lo_gives_way = ((cid & 1ULL) == 0ULL);
                rule = RULE_FAIR_COIN;
            }
        }
    }

    v.deciding_rule = rule;
    v.conjunction_id = cid;
    v.give_way_id = lo_gives_way ? lo->object_id : hi->object_id;
    v.advisory = (!cm_lo) && (!cm_hi);
    v.self_role = sb_id_equal(&v.give_way_id, &self->object_id)
                      ? ROLE_GIVE_WAY : ROLE_STAND_ON;
    return v;
}

/* ==== maneuver.c ==== */
// SPDX-License-Identifier: AGPL-3.0-or-later
// Starboard Protocol — reference implementation (C99 port)
// Copyright (C) 2026 James H. All rights reserved.
// Dual licensing: see COMMERCIAL-LICENSE.md.
//
// maneuver.c — Hill (RIC) frame, Clohessy-Wiltshire state transition, the
// minimum-dv give-way burn and the mirror+phase / quarter-period returns.
// Operation-for-operation transliteration of frames.hpp + maneuver.hpp (same
// expansion order, same canon_sincos), so the C99 port reproduces the C++
// maneuver plans bit-for-bit (conformance/expected_bits_ext.txt). Maneuver
// quantities are OFF the normative verdict path (SPEC §3.5); bit-equality
// here is a cross-language cross-check, not a protocol requirement.

/* #include "starboard.h" (amalgamated) */
#include <math.h>

Mat3 sb_mat3_identity(void)
{
    Mat3 m;
    int i;
    int j;
    for (i = 0; i < 3; ++i)
    {
        for (j = 0; j < 3; ++j)
        {
            m.m[i][j] = (i == j) ? 1.0 : 0.0;
        }
    }
    return m;
}

Vec3 sb_mat3_mul(const Mat3 *a, Vec3 v)
{
    Vec3 r;
    r.x = ((a->m[0][0] * v.x) + (a->m[0][1] * v.y)) + (a->m[0][2] * v.z);
    r.y = ((a->m[1][0] * v.x) + (a->m[1][1] * v.y)) + (a->m[1][2] * v.z);
    r.z = ((a->m[2][0] * v.x) + (a->m[2][1] * v.y)) + (a->m[2][2] * v.z);
    return r;
}

Vec3 sb_mat3_tmul(const Mat3 *a, Vec3 v)
{
    Vec3 r;
    r.x = ((a->m[0][0] * v.x) + (a->m[1][0] * v.y)) + (a->m[2][0] * v.z);
    r.y = ((a->m[0][1] * v.x) + (a->m[1][1] * v.y)) + (a->m[2][1] * v.z);
    r.z = ((a->m[0][2] * v.x) + (a->m[1][2] * v.y)) + (a->m[2][2] * v.z);
    return r;
}

Vec3 sb_mat3_solve(const Mat3 *a, Vec3 b)
{
    const double c00 = (a->m[1][1] * a->m[2][2]) - (a->m[1][2] * a->m[2][1]);
    const double c01 = (a->m[1][2] * a->m[2][0]) - (a->m[1][0] * a->m[2][2]);
    const double c02 = (a->m[1][0] * a->m[2][1]) - (a->m[1][1] * a->m[2][0]);
    const double det = ((a->m[0][0] * c00) + (a->m[0][1] * c01)) +
                       (a->m[0][2] * c02);
    const double inv = 1.0 / det;
    const double c10 = (a->m[0][2] * a->m[2][1]) - (a->m[0][1] * a->m[2][2]);
    const double c11 = (a->m[0][0] * a->m[2][2]) - (a->m[0][2] * a->m[2][0]);
    const double c12 = (a->m[0][1] * a->m[2][0]) - (a->m[0][0] * a->m[2][1]);
    const double c20 = (a->m[0][1] * a->m[1][2]) - (a->m[0][2] * a->m[1][1]);
    const double c21 = (a->m[0][2] * a->m[1][0]) - (a->m[0][0] * a->m[1][2]);
    const double c22 = (a->m[0][0] * a->m[1][1]) - (a->m[0][1] * a->m[1][0]);
    Vec3 r;
    r.x = (((c00 * b.x) + (c10 * b.y)) + (c20 * b.z)) * inv;
    r.y = (((c01 * b.x) + (c11 * b.y)) + (c21 * b.z)) * inv;
    r.z = (((c02 * b.x) + (c12 * b.y)) + (c22 * b.z)) * inv;
    return r;
}

Mat3 sb_hill_basis(CraftState s)
{
    const Vec3 rhat = sb_vnormalized(s.position);
    const Vec3 chat = sb_vnormalized(sb_vcross(s.position, s.velocity));
    const Vec3 ihat = sb_vcross(chat, rhat);
    Mat3 m;
    m.m[0][0] = rhat.x; m.m[0][1] = rhat.y; m.m[0][2] = rhat.z;
    m.m[1][0] = ihat.x; m.m[1][1] = ihat.y; m.m[1][2] = ihat.z;
    m.m[2][0] = chat.x; m.m[2][1] = chat.y; m.m[2][2] = chat.z;
    return m;
}

double sb_mean_motion(CraftState s)
{
    const double a = sb_quantize(sb_vnorm(s.position), SB_Q_POS_M);
    return sqrt(SB_MU_EARTH_M3S2 / ((a * a) * a));
}

static Mat3 sb_mat3_zero(void)
{
    Mat3 m;
    int i;
    int j;
    for (i = 0; i < 3; ++i)
    {
        for (j = 0; j < 3; ++j)
        {
            m.m[i][j] = 0.0;
        }
    }
    return m;
}

Mat3 sb_cw_phi_rr(double n, double t)
{
    double s;
    double c;
    Mat3 m = sb_mat3_zero();
    sb_canon_sincos(n * t, &s, &c);
    m.m[0][0] = 4.0 - (3.0 * c);
    m.m[1][0] = 6.0 * (s - (n * t));
    m.m[1][1] = 1.0;
    m.m[2][2] = c;
    return m;
}

Mat3 sb_cw_phi_rv(double n, double t)
{
    double s;
    double c;
    Mat3 m = sb_mat3_zero();
    sb_canon_sincos(n * t, &s, &c);
    m.m[0][0] = s / n;
    m.m[0][1] = (2.0 * (1.0 - c)) / n;
    m.m[1][0] = (-2.0 * (1.0 - c)) / n;
    m.m[1][1] = ((4.0 * s) - ((3.0 * n) * t)) / n;
    m.m[2][2] = s / n;
    return m;
}

Mat3 sb_cw_phi_vr(double n, double t)
{
    double s;
    double c;
    Mat3 m = sb_mat3_zero();
    sb_canon_sincos(n * t, &s, &c);
    m.m[0][0] = (3.0 * n) * s;
    m.m[1][0] = (-6.0 * n) * (1.0 - c);
    m.m[2][2] = (-n) * s;
    return m;
}

Mat3 sb_cw_phi_vv(double n, double t)
{
    double s;
    double c;
    Mat3 m = sb_mat3_zero();
    sb_canon_sincos(n * t, &s, &c);
    m.m[0][0] = c;
    m.m[0][1] = 2.0 * s;
    m.m[1][0] = -2.0 * s;
    m.m[1][1] = (4.0 * c) - 3.0;
    m.m[2][2] = c;
    return m;
}

HillState sb_cw_propagate(HillState x0, double n, double t)
{
    const Mat3 rr = sb_cw_phi_rr(n, t);
    const Mat3 rv = sb_cw_phi_rv(n, t);
    const Mat3 vr = sb_cw_phi_vr(n, t);
    const Mat3 vv = sb_cw_phi_vv(n, t);
    HillState x;
    x.r = sb_vadd(sb_mat3_mul(&rr, x0.r), sb_mat3_mul(&rv, x0.v));
    x.v = sb_vadd(sb_mat3_mul(&vr, x0.r), sb_mat3_mul(&vv, x0.v));
    return x;
}

/* SPEC §6.4 — see maneuver.hpp for the derivation and the Theorem 2
 * argument for the degenerate zero-miss push direction. */
GiveWayPlan sb_plan_give_way(CraftState self_now, CraftState self_tca,
                             const Conjunction *conj,
                             bool self_is_canonical_lo, double r_safe)
{
    GiveWayPlan plan;
    const double target = SB_MANEUVER_MARGIN * r_safe;
    const bool pc_hot = (conj->pc >= SB_PC_ACTIONABLE);
    double n;
    double tau;
    Vec3 u_away_eci;
    double d_needed;
    Vec3 u_hill;
    Mat3 basis_tca;
    Mat3 basis_now;
    Mat3 phi;
    Vec3 w;
    double w2;

    if ((conj->miss_distance >= target) && (!pc_hot))
    {
        plan.required = false;
        plan.dv_eci.x = 0.0;
        plan.dv_eci.y = 0.0;
        plan.dv_eci.z = 0.0;
        plan.dv_hill = plan.dv_eci;
        plan.dv_mag = 0.0;
        plan.displacement_m = 0.0;
        return plan;
    }
    plan.required = true;

    n = sb_mean_motion(self_now);
    tau = (conj->t_ca > SB_MIN_LEAD_S) ? conj->t_ca : SB_MIN_LEAD_S;

    if (conj->miss_distance > SB_EPS_LATERAL_M)
    {
        u_away_eci = sb_vscale(conj->miss_vector,
                               (-1.0 / conj->miss_distance));
    }
    else
    {
        const double dvn = sb_vnorm(conj->rel_velocity);
        Vec3 axis;
        Vec3 p;
        if (dvn > 1.0e-9)
        {
            axis = sb_vdiv(conj->rel_velocity, dvn);
        }
        else
        {
            axis = sb_vnormalized(self_now.position);
        }
        p = sb_pinned_perpendicular(axis);
        u_away_eci = self_is_canonical_lo ? p : sb_vscale(p, -1.0);
    }
    d_needed = (conj->miss_distance < target)
                   ? (target - conj->miss_distance)
                   : target;

    basis_tca = sb_hill_basis(self_tca);
    u_hill = sb_mat3_mul(&basis_tca, u_away_eci);
    phi = sb_cw_phi_rv(n, tau);
    w = sb_mat3_tmul(&phi, u_hill);
    w2 = sb_vdot(w, w);

    if (w2 > 1.0e-12)
    {
        plan.dv_hill = sb_vscale(w, (d_needed / w2));
    }
    else
    {
        plan.dv_hill = sb_vscale(u_hill, (d_needed / tau));
    }
    basis_now = sb_hill_basis(self_now);
    plan.dv_eci = sb_mat3_tmul(&basis_now, plan.dv_hill);
    plan.dv_mag = sb_vnorm(plan.dv_hill);
    plan.displacement_m = sb_vdot(sb_mat3_mul(&phi, plan.dv_hill), u_hill);
    return plan;
}

MirrorReturnPlan sb_plan_mirror_return(Vec3 giveway_dv_hill, double n,
                                       int phasing_orbits)
{
    MirrorReturnPlan plan;
    const double period = (2.0 * SB_PI) / n;
    const double y_off = ((-6.0 * SB_PI) * giveway_dv_hill.y) / n;
    const double dv_p =
        (y_off * n) / ((6.0 * SB_PI) * (double)phasing_orbits);
    Vec3 phase;
    phase.x = 0.0;
    phase.y = dv_p;
    phase.z = 0.0;
    plan.mirror_dv_hill = sb_vadd(sb_vscale(giveway_dv_hill, -1.0), phase);
    plan.final_dv_hill = sb_vscale(phase, -1.0);
    plan.wait_s = period;
    plan.transfer_s = period * (double)phasing_orbits;
    plan.total_dv = sb_vnorm(plan.mirror_dv_hill) +
                    sb_vnorm(plan.final_dv_hill);
    return plan;
}

ReturnPlan sb_plan_return(HillState offset, double n)
{
    ReturnPlan plan;
    Mat3 rr;
    Mat3 rv;
    Mat3 vr;
    Mat3 vv;
    Vec3 v_required;
    Vec3 v_arrival;

    plan.transfer_s = (0.5 * SB_PI) / n;
    rr = sb_cw_phi_rr(n, plan.transfer_s);
    rv = sb_cw_phi_rv(n, plan.transfer_s);
    vr = sb_cw_phi_vr(n, plan.transfer_s);
    vv = sb_cw_phi_vv(n, plan.transfer_s);

    v_required = sb_mat3_solve(&rv, sb_vscale(sb_mat3_mul(&rr, offset.r),
                                               -1.0));
    plan.dv1_hill = sb_vsub(v_required, offset.v);
    v_arrival = sb_vadd(sb_mat3_mul(&vr, offset.r),
                        sb_mat3_mul(&vv, v_required));
    plan.dv2_hill = sb_vscale(v_arrival, -1.0);
    plan.total_dv = sb_vnorm(plan.dv1_hill) + sb_vnorm(plan.dv2_hill);
    return plan;
}

/* ==== multibody.c ==== */
// SPDX-License-Identifier: AGPL-3.0-or-later
// Starboard Protocol — reference implementation (C99 port)
// Copyright (C) 2026 James H. All rights reserved.
// Dual licensing: see COMMERCIAL-LICENSE.md.
//
// multibody.c — Layer 7 single-pass window cascade (SPEC §7). Transliteration
// of multibody.hpp: canonical (TCA bucket, conjunction id) insertion sort,
// sticky role locks, advisory verdicts record no locks, malformed windows
// rejected before anything is indexed. Fixed capacity, no allocation.

/* #include "starboard.h" (amalgamated) */

#define SB_LOCK_NONE     (0U)
#define SB_LOCK_STAND_ON (1U)
#define SB_LOCK_GIVE_WAY (2U)

uint32_t sb_resolve_window(const CraftDescriptor *craft, uint32_t n_craft,
                           WindowEntry *entries, uint32_t n_entries,
                           WindowVerdict *out)
{
    uint64_t cid[SB_MAX_WINDOW_CONJ];
    uint8_t locks[SB_MAX_WINDOW_CRAFT];
    uint32_t i;

    if ((n_craft > SB_MAX_WINDOW_CRAFT) || (n_entries > SB_MAX_WINDOW_CONJ))
    {
        return 0U;
    }
    for (i = 0U; i < n_entries; ++i)
    {
        if ((entries[i].a >= n_craft) || (entries[i].b >= n_craft) ||
            (entries[i].a == entries[i].b))
        {
            return 0U;
        }
    }

    for (i = 0U; i < n_entries; ++i)
    {
        cid[i] = sb_conjunction_id(&craft[entries[i].a].object_id,
                                   &craft[entries[i].b].object_id,
                                   entries[i].tca_epoch_ms);
    }
    for (i = 1U; i < n_entries; ++i)
    {
        const WindowEntry key = entries[i];
        const uint64_t key_cid = cid[i];
        const uint64_t key_bucket = key.tca_epoch_ms / SB_TCA_BUCKET_MS;
        uint32_t j = i;
        while (j > 0U)
        {
            const uint64_t pb = entries[j - 1U].tca_epoch_ms / SB_TCA_BUCKET_MS;
            const bool before = (key_bucket != pb) ? (key_bucket < pb)
                                                   : (key_cid < cid[j - 1U]);
            if (!before)
            {
                break;
            }
            entries[j] = entries[j - 1U];
            cid[j] = cid[j - 1U];
            --j;
        }
        entries[j] = key;
        cid[j] = key_cid;
    }

    for (i = 0U; i < SB_MAX_WINDOW_CRAFT; ++i)
    {
        locks[i] = SB_LOCK_NONE;
    }

    for (i = 0U; i < n_entries; ++i)
    {
        const WindowEntry *e = &entries[i];
        CraftDescriptor a = craft[e->a];
        CraftDescriptor b = craft[e->b];
        WindowVerdict wv;
        const uint8_t la = locks[e->a];
        const uint8_t lb = locks[e->b];

        a.state = e->a_tca;
        b.state = e->b_tca;
        wv.conjunction_id = cid[i];

        if ((la == SB_LOCK_GIVE_WAY) != (lb == SB_LOCK_GIVE_WAY))
        {
            /* Cascade: the already-maneuvering craft absorbs this pair. */
            const bool a_gives = (la == SB_LOCK_GIVE_WAY);
            wv.give_way_index = a_gives ? e->a : e->b;
            wv.stand_on_index = a_gives ? e->b : e->a;
            wv.deciding_rule = RULE_CASCADE;
            wv.advisory = false;
        }
        else
        {
            GiveWayVerdict v;
            bool a_gives;
            /* A stand-on lock is a committed trajectory: Rule 1 incapable. */
            if (la == SB_LOCK_STAND_ON)
            {
                a.can_maneuver = false;
            }
            if (lb == SB_LOCK_STAND_ON)
            {
                b.can_maneuver = false;
            }
            v = sb_evaluate(&a, &b, e->tca_epoch_ms);
            a_gives = sb_id_equal(&v.give_way_id, &a.object_id);
            wv.give_way_index = a_gives ? e->a : e->b;
            wv.stand_on_index = a_gives ? e->b : e->a;
            wv.deciding_rule = v.deciding_rule;
            wv.advisory = v.advisory;
        }

        wv.escalated = (locks[wv.give_way_index] == SB_LOCK_STAND_ON);

        /* Advisory verdicts commit nobody (SPEC §7.3). */
        if (!wv.advisory)
        {
            if (locks[wv.give_way_index] == SB_LOCK_NONE)
            {
                locks[wv.give_way_index] = SB_LOCK_GIVE_WAY;
            }
            if (locks[wv.stand_on_index] == SB_LOCK_NONE)
            {
                locks[wv.stand_on_index] = SB_LOCK_STAND_ON;
            }
        }
        out[i] = wv;
    }
    return n_entries;
}

/* ==== broadphase.c ==== */
// SPDX-License-Identifier: AGPL-3.0-or-later
// Starboard Protocol — reference implementation (C99 port)
// Copyright (C) 2026 James H. All rights reserved.
// Dual licensing: see COMMERCIAL-LICENSE.md.
//
// broadphase.c — Stage-1 radial-band sweep (SPEC §4.8). Same gate as the C++
// reference (identical radial_bounds on the identical canonical state, margin
// R_SCREEN), so recall = 1.0 unconditionally. std::sort is replaced by an
// in-place, non-recursive heapsort keyed on (lo, original index): O(N log N),
// no allocation, no recursion, and — unlike std::sort — a TOTAL order, so the
// emitted pair list is itself deterministic across implementations. (SPEC
// §4.8 only requires the candidate SET to be a superset; the C++ reference
// may list the same set in another order.)

/* #include "starboard.h" (amalgamated) */

static bool sb_band_less(const SbBand *x, const SbBand *y)
{
    if (x->lo != y->lo)
    {
        return x->lo < y->lo;
    }
    return x->idx < y->idx;
}

static void sb_sift_down(SbBand *b, uint32_t start, uint32_t end)
{
    uint32_t root = start;
    for (;;)
    {
        uint32_t child = (2U * root) + 1U;
        uint32_t swap = root;
        SbBand t;
        if (child > end)
        {
            break;
        }
        if (sb_band_less(&b[swap], &b[child]))
        {
            swap = child;
        }
        if (((child + 1U) <= end) && sb_band_less(&b[swap], &b[child + 1U]))
        {
            swap = child + 1U;
        }
        if (swap == root)
        {
            break;
        }
        t = b[root];
        b[root] = b[swap];
        b[swap] = t;
        root = swap;
    }
}

static void sb_heapsort_bands(SbBand *b, uint32_t n)
{
    uint32_t end;
    uint32_t start;
    if (n < 2U)
    {
        return;
    }
    start = (n - 2U) / 2U;
    for (;;)
    {
        sb_sift_down(b, start, n - 1U);
        if (start == 0U)
        {
            break;
        }
        --start;
    }
    end = n - 1U;
    while (end > 0U)
    {
        const SbBand t = b[end];
        b[end] = b[0];
        b[0] = t;
        --end;
        sb_sift_down(b, 0U, end);
    }
}

uint32_t sb_radial_band_pairs(const CraftState *objs, uint32_t n,
                              SbBand *bands, uint32_t *active,
                              SbPair *out, uint32_t cap, bool *overflow,
                              double margin)
{
    uint32_t k;
    uint32_t j;
    uint32_t count = 0U;
    uint32_t n_active = 0U;

    if (overflow != NULL)
    {
        *overflow = false;
    }
    for (k = 0U; k < n; ++k)
    {
        double rlo;
        double rhi;
        sb_radial_bounds(sb_canonicalize(objs[k]), &rlo, &rhi);
        bands[k].lo = rlo - margin;
        bands[k].hi = rhi + margin;
        bands[k].idx = k;
    }
    sb_heapsort_bands(bands, n);

    for (j = 0U; j < n; ++j)
    {
        const double lo_j = bands[j].lo;
        const uint32_t ib = bands[j].idx;
        uint32_t w = 0U;
        uint32_t s;
        for (s = 0U; s < n_active; ++s)
        {
            const uint32_t a = active[s];
            uint32_t ia;
            if (bands[a].hi < lo_j)
            {
                continue;
            }
            active[w] = a;
            ++w;
            ia = bands[a].idx;
            if (count >= cap)
            {
                if (overflow != NULL)
                {
                    *overflow = true;
                }
                return count;
            }
            out[count].i = (ia < ib) ? ia : ib;
            out[count].j = (ia < ib) ? ib : ia;
            ++count;
        }
        n_active = w;
        active[n_active] = j;
        ++n_active;
    }
    return count;
}

